/* New Meridian processes (v8): Finance & procurement, Outreach & communications, Legal, compliance & audit. Pure data, no imports. */
export const MORE = [

 /* ---------------- Finance & procurement ---------------- */
 {fn:'finance', area:'fin-payables',
  proc:{id:'pcard', name:'Purchase card reconciliation', d:'Code each card purchase, approve the monthly statements and check card spending for misuse.', rating:3, why:'Steady volume on clean card data, but most of the gain is rules and a better approval design. Anomaly detection is the one real AI piece.'},
  intro:'About 310 staff hold a Bank purchase card for small buys: books, training, software and conference fees. Every month each card line must be receipted, coded and approved, and finance checks for misuse. Walk a month of card spending.',
  steps:[
  {n:'Code each purchase', who:'Cardholders', vol:'About 2,600 card lines a month from 310 cardholders', sys:'Card portal, card issuer feed, receipt photos',
   notes:'Each month the card issuer’s feed lands in the card portal. Cardholders open every line, attach a photo of the receipt, choose a cost centre and one of 180 account codes, and type a business purpose.',
   pain:'Cardholders say it takes six minutes a line, about 260 hours a month across the Bank. One line in five is coded to the wrong account and recoded by finance at month end.',
   p:'route structured high low', alt:'shape:extract', best:'rules', ok:'classify', auto:'auto', autoOk:'review',
   why:'Most of the coding follows from facts already in the feed: the cardholder’s cost centre and the merchant’s category. Default those with rules, and ask the cardholder only for the business purpose and the few lines rules cannot code.',
   disc:[['Merchant categories','Every card line already carries the merchant’s category code from the card network.','Data: about three lines in four can be coded from the category alone.'],['Online marketplaces','Purchases from large online marketplaces could be anything, from cables to books.','Keep: these lines still need the cardholder to choose the code.']],
   fv:'high mid', reality:'Configuration on data that already arrives clean. Medium value: cardholder hours back, and fewer recodes at month end.',
   metric:'Minutes per card line for cardholders, and lines recoded by finance', g:'logging rollback sampling', hyp:'Three lines in four coded before the cardholder opens the statement.', data:'The card issuer feed with merchant category codes, cardholders’ cost centres, a year of coded lines.'},
  {n:'Chase manager approvals', who:'Card programme administrator', vol:'About 210 approving managers, every month', sys:'Card portal, email',
   notes:'Once cardholders have reconciled, each line manager must approve their team’s statements in the card portal. The administrator chases the late approvals by email until month-end close.',
   pain:'Approvals take nine days to complete each month. Portal logs show most managers spend under ten seconds per statement, and approval has not caught a breach in three years.',
   p:'coordinate structured high low', alt:'shape:check', best:'fix', ok:'rules agent', auto:'review',
   why:'The approval adds delay and catches nothing, because nobody can judge a list of card lines in ten seconds. Replace the blanket sign-off with managers reviewing only the lines finance flags. Then there is little left to chase.',
   disc:[['Ten seconds a statement','Portal logs show managers open each statement for under ten seconds on average.','Fix first: an approval nobody reads is not a control.'],['The policy says so','The card policy, last revised in 2016, requires every statement to be approved.','Rule: agree the change with internal audit and update the policy before changing the process.']],
   fv:'high mid', reality:'Easy to change once audit and the policy agree. Medium value: nine days off the monthly close, and managers’ time back.',
   metric:'Days from statement to complete approval, and breaches caught at approval', g:'logging sampling', hyp:'Close the card month in two days, with managers looking only at flagged lines.', data:'Portal approval logs and three years of breach findings.'},
  {n:'Review card spending for policy breaches', who:'Card programme administrator and a finance analyst', vol:'About 2,600 card lines a month, three years of history', sys:'Card portal, card issuer feed, spreadsheet',
   notes:'Finance runs a monthly report of every line over $2,500 and samples a few more, looking for split purchases, banned merchant types, weekend spending and personal use. Questionable lines go back to the cardholder for an explanation.',
   pain:'The fixed report catches large purchases but misses patterns. Last year a cardholder split a $9,000 purchase into four lines under the single-purchase limit, and external audit found it, not finance.',
   p:'check structured high mid', alt:'shape:predict', best:'anomaly', ok:'rules', auto:'review', autoOk:'assist',
   why:'Score every line for the patterns that matter: splits, unusual merchants, and amounts or times unusual for that cardholder. The administrator reviews the flagged lines; nothing is decided about anyone automatically.',
   disc:[['Rules for the known patterns','Split purchases and banned merchant types can be written down exactly.','Keep: use rules for the known patterns and anomaly scores for the rest.'],['Few confirmed cases','The feed holds three years of lines but only 41 confirmed breaches.','Data: judge the pilot on how many flags lead to a real question, not on catching past cases.']],
   fv:'high mid', reality:'Ready data and a modest build. Medium value: breaches found by finance within the month, and less sampling by hand.',
   metric:'Breaches found by finance before audit, and flags that lead to a real question', g:'threshold sampling logging', hyp:'Every split purchase found within the month, from fewer than 30 flags.', data:'Three years of card lines, the card policy limits, confirmed breaches.'},
 ]},

 {fn:'finance', area:'fin-procure',
  proc:{id:'duediligence', name:'Supplier due diligence', d:'Check new suppliers’ questionnaires, assess their financial standing and review their information security.', rating:2, why:'Modest volume and real judgment. The security review carries the reading load; the rest needs one current set of forms and the services the Bank already pays for.'},
  intro:'Before the Bank signs with a new supplier, procurement must know who it is dealing with: whether the supplier is sound, clean and safe to trust with data. That means three questionnaires, read and assessed by people. Walk a new supplier from questionnaire to sign-off.',
  steps:[
  {n:'Check the returned questionnaires', who:'Procurement officers', vol:'About 180 new suppliers a year, three questionnaires each', sys:'Email, Word and PDF questionnaires, supplier register',
   notes:'New suppliers return the financial, sanctions and information security questionnaires by email, often with policies and certificates attached. Officers read every answer to check nothing is missing and record the result in the supplier register.',
   pain:'Six in ten come back incomplete, and suppliers fill in old versions of the forms. Officers spend about two hours per supplier before any assessment starts.',
   p:'extract text mid mid', alt:'shape:check', best:'extract', ok:'classify rules', auto:'review',
   why:'Read each returned questionnaire, pull the answers into the register and list what is missing, so the officer sends one clear request back. Retire the old versions of the forms first.',
   disc:[['Five versions in use','Suppliers are filling in five different versions of the questionnaires, some ten years old.','Prepare: withdraw the old versions and publish one current set.'],['A form, not a document','The e-procurement system has a supplier form module the Bank has never switched on.','Fix first: move the standard questions into the form, and keep extraction for the attachments.']],
   fv:'mid mid', reality:'Worth doing once there is one current version of each questionnaire. Medium value: about 30 officer hours a month and a faster start to each contract.',
   metric:'Officer hours per supplier before assessment, and questionnaires returned for missing answers', g:'threshold sampling', hyp:'Every questionnaire checked within a day of arrival, with one request for anything missing.', data:'A year of returned questionnaires and the register entries made from them.'},
  {n:'Assess financial standing', who:'Procurement officers', vol:'About 70 suppliers a year above the $250,000 threshold', sys:'Credit reference service, supplier accounts, scoring spreadsheet',
   notes:'For larger contracts, officers read two years of the supplier’s accounts, work out a few ratios and compare them with the credit score the Bank already buys. Sanctions screening is separate: the screening service checks every supplier automatically.',
   pain:'About three hours per supplier. Officers who are not accountants are unsure what the ratios mean, and two officers rated the same supplier differently last year.',
   p:'check text low mid', alt:'input:structured', best:'extract', ok:'rules', auto:'review',
   why:'Seventy a year, and the credit service already reports the ratios and a failure score. A one-page guide on when to look deeper, with the hard cases sent to an accountant, is the right size.',
   disc:[['Already bought','The credit reference service includes ratios and a failure score for most suppliers.','Value: read the report the Bank already pays for before re-keying anyone’s accounts.'],['Accountants down the hall','Finance has six qualified accountants two floors away.','Keep: send the borderline cases to one of them.']],
   fv:'high low', reality:'Easy, and too small to be worth a tool. A short guide and the existing service are enough.',
   metric:'Hours per financial check, and suppliers that fail within a year of award', g:'sampling', hyp:'A clear financial check in under an hour, with the hard cases seen by an accountant.', data:'Credit reports for current suppliers, the threshold rules.'},
  {n:'Review the information security answers', who:'Information security analysts', vol:'About 60 suppliers a year, 220 questions each plus assurance reports', sys:'Security questionnaire, independent assurance reports, risk register',
   notes:'Suppliers that will hold Bank data or connect to its systems answer 220 security questions and send independent assurance reports, often over 100 pages. An analyst reads them against the Bank’s minimum controls and recommends approve, approve with conditions, or reject.',
   pain:'Each review takes two to three days. Procurement waits a median of five weeks for security sign-off, and contracts start late.',
   p:'check text mid high', alt:'shape:decide', best:'extract recommend', ok:'retrieve summarize', auto:'assist',
   why:'Pull each answer and the matching evidence from the assurance report into the Bank’s control list, and flag gaps and answers with no evidence behind them. The analyst judges the risk and signs off.',
   disc:[['Answers are not evidence','Suppliers often answer “yes” to a control that their own assurance report says failed.','Risk: compare every answer with the report, not just the answer itself.'],['Shared in confidence','Assurance reports are shared under non-disclosure terms.','Data: the tool must run inside the Bank’s approved environment.']],
   fv:'mid high', reality:'High value on the contract’s critical path, and high stakes. Assist only, inside the approved environment.',
   metric:'Analyst days per review, and weeks from questionnaire to security sign-off', g:'logging escalation sampling privacy', hyp:'Cut a review from three days to one, with every gap traced to the evidence.', data:'Past questionnaires with analysts’ decisions, the minimum control list, sample assurance reports.'},
 ]},

 {fn:'finance', area:'fin-controls',
  proc:{id:'variance', name:'Budget variance commentary', d:'Report spending against budget, collect the reasons for variances and summarise them for leadership.', rating:3, why:'A monthly cycle with real effort, but half of it exists because budgets are split evenly across the year. Fix that and build the report; then summarising is a safe win.'},
  intro:'Every month, finance compares what each team spent with its budget, asks budget holders why, and tells the president’s management committee what matters. Walk a month from close to the leadership pack.',
  steps:[
  {n:'Produce the variance report', who:'Management accountants', vol:'Monthly, 140 cost centres', sys:'ERP, budget system, Excel workbook',
   notes:'After month-end close, accountants export actuals from the ERP and the budget from the budget system, paste both into a workbook with a tab per division, and highlight every line over the threshold of 10% and $20,000.',
   pain:'Three days every month. Twice last year a broken formula sent budget holders the wrong numbers.',
   p:'check structured high mid', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Comparing actuals with budget against a fixed threshold is a report, not a judgment. Build it once from the ledger and run it the morning after close.',
   disc:[['Both systems hold the data','Actuals and budget are both held by cost centre and account.','Feasibility: a report, not a project.'],['An old threshold','The 10% and $20,000 threshold has not been reviewed since 2014.','Rule: agree the threshold with budget holders while building the report.']],
   fv:'high mid', reality:'Plain engineering on data that already exists. Medium value: three days a month and no broken formulas.',
   metric:'Days from close to variance report, and reports reissued for errors', g:'logging rollback', hyp:'The variance report out the morning after close, every month.', data:'The ERP ledger and the budget system, by cost centre and account.'},
  {n:'Collect explanations from budget holders', who:'Finance business partners and 140 budget holders', vol:'About 350 lines a month needing a comment', sys:'Email, Excel template',
   notes:'Business partners send each budget holder the lines over the threshold and ask why. Budget holders reply with a sentence a line, from memory, and partners chase the late ones.',
   pain:'Six days of chasing each month. Six comments in ten say only “timing”, because annual budgets are split into twelve equal months while spending is not.',
   p:'coordinate tacit high mid', alt:'input:text shape:draft', best:'fix', ok:'rules agent', auto:'review',
   why:'Most of these variances are not real. Spread each budget across the months when the money will actually be spent, and most “timing” lines disappear. The reasons that remain are in budget holders’ heads; no tool can write them, and a drafted reason would be invented.',
   disc:[['Twelve equal months','Budgets are split evenly across the year, though contracts, licences and conferences are paid in lumps.','Fix first: phase each budget to when the spending is planned.'],['Drafting the reasons','A manager suggested drafting the comments from the numbers.','Risk: a drafted reason reads well and is made up; only the budget holder knows why.']],
   fv:'high mid', reality:'A process fix finance controls itself. Medium value: about half the lines and most of the chasing go away.',
   metric:'Lines needing a comment each month, and share of comments that say only “timing”', g:'logging', hyp:'Halve the lines needing comment, and make the rest worth reading.', data:'Planned payment dates for contracts, licences and events, by cost centre.'},
  {n:'Compile the commentary for the leadership pack', who:'Head of financial planning', vol:'Monthly, 350 comments into a two-page summary', sys:'Excel template, Word, leadership pack',
   notes:'The head of financial planning reads every comment, picks out the ten that matter, and writes two pages for the leadership pack that goes to the president and the management committee.',
   pain:'Two days each month of reading and rewriting, squeezed into the 48 hours before the pack is due.',
   p:'summarize text mid mid', alt:'shape:draft', best:'summarize', ok:'classify draft', auto:'review',
   why:'Group the comments by theme and size, and draft the two-page summary with every figure linked to its line in the report. The head of financial planning edits and owns it.',
   disc:[['Figures must tie','Leaders quote the pack’s figures back in meetings.','Rule: every figure in the summary links to the variance report.'],['Easier after the fix','Once the “timing” lines are gone, there is less to read and more worth saying.','Value: this step gets quicker after the phasing fix.']],
   fv:'high mid', reality:'Quick to do on comments that already arrive in one template. Medium value: two days a month of a senior person’s time.',
   metric:'Hours to produce the summary, and figures corrected after the pack is sent', g:'sampling logging', hyp:'The summary drafted in an hour, with every figure traced to the report.', data:'The monthly comments, the variance report and past leadership packs.'},
 ]},

 {fn:'finance', area:'fin-controls',
  proc:{id:'fixedassets', name:'Fixed asset register', d:'Record additions and disposals, run depreciation and check that assets still exist.', rating:2, why:'Structured data and fixed rules. The register needs integration and a configured depreciation run, not AI, and the yearly count is too small for a tool.'},
  intro:'The Bank owns about 11,000 things worth recording: buildings, chillers, vault equipment, vehicles, servers and laptops. Each must be on the register, depreciated every month and found once a year. Walk the register.',
  steps:[
  {n:'Record additions and disposals', who:'Fixed asset accountant', vol:'About 140 additions and 90 disposals a month, 11,000 assets in all', sys:'ERP, asset register, IT recycling log, email',
   notes:'When a capital purchase is received, the accountant creates the asset on the register: category, cost, location and useful life. Disposals arrive as emails from IT and facilities, when someone remembers to send them.',
   pain:'Two days a month of keying. Last year’s count found 600 laptops still on the register that IT had already recycled.',
   p:'extract structured high mid', alt:'input:text', best:'rules', ok:'extract agent', auto:'auto', autoOk:'review',
   why:'The purchase order already says the item is capital and which category it belongs to. Create the asset from the goods receipt automatically, and take disposals straight from IT’s recycling log instead of waiting for an email.',
   disc:[['The order knows','Capital purchase orders already carry an asset category.','Feasibility: integration between two modules of the same ERP.'],['Disposals nobody reports','Facilities disposes of furniture and plant without telling finance.','Fix first: add a finance step to the facilities disposal form.']],
   fv:'high mid', reality:'Integration on data the ERP already holds. Medium value: two days a month, and a register that matches what is really there.',
   metric:'Hours keying assets, and assets found disposed of but still on the register', g:'logging rollback', hyp:'Every addition and disposal on the register within a day, with no keying.', data:'Capital purchase orders and goods receipts, IT’s recycling log.'},
  {n:'Run monthly depreciation', who:'Fixed asset accountant', vol:'Monthly, 11,000 assets', sys:'Spreadsheet, ERP journal',
   notes:'Depreciation is worked out in a spreadsheet from each asset’s cost, useful life and start date, then posted to the ledger as a manual journal. The ERP’s depreciation module was bought with the system and never set up.',
   pain:'A day each month, and external audit has raised the spreadsheet as a control weakness two years running.',
   p:'coordinate structured high mid', alt:'shape:check', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Depreciation is arithmetic on fixed rules: cost, useful life and method. Set up the ERP’s module and let it post the journal each month. No AI is needed, and the spreadsheet goes.',
   disc:[['Already paid for','The depreciation module is part of the ERP licence.','Feasibility: configuration, plus loading the opening balances once.'],['Useful lives','Some useful lives in the spreadsheet were typed by hand and differ from the policy.','Rule: load useful lives from the policy table, not from the old spreadsheet.']],
   fv:'high mid', reality:'Configuration of software the Bank already owns. Medium value: a day a month and an audit finding closed.',
   metric:'Hours on the monthly run, and audit findings on depreciation', g:'logging rollback', hyp:'Depreciation posted automatically on the first working day of each month.', data:'The asset register, the useful-life policy table, the ERP module.'},
  {n:'Check that assets still exist', who:'Finance staff with facilities and IT', vol:'Once a year, about 11,000 assets in three buildings', sys:'Register extract, barcode scanners, IT device records',
   notes:'Each year teams walk every floor with barcode scanners and a register extract, find each asset and mark what is missing. Missing items are investigated and written off.',
   pain:'Three weeks for six people every year. Laptops are the hardest to find, because they travel with their owners.',
   p:'physical structured low mid', alt:'shape:check', best:'vision', ok:'rules', auto:'review',
   why:'Once a year is too rare to pay for a vision or tracking tool. The cheaper move is to stop walking for laptops: IT already sees every laptop that connects, so count only what cannot report itself.',
   disc:[['Laptops report in','IT’s device records show every laptop that has connected to the network in the last month.','Fix first: take laptops out of the walk-round and reconcile them from IT’s records.'],['Labels that peel','About one barcode label in twelve has peeled off or faded.','Keep: re-label as you count; it costs little.']],
   fv:'high low', reality:'Easy to improve, but too small for a tool. Use the records IT already has, and keep the walk-round for the rest.',
   metric:'Staff days spent on the count, and assets not found', g:'sampling', hyp:'The count finished in one week, with laptops reconciled from IT’s records.', data:'The register, IT’s device records, the floor plans.'},
 ]},

 /* ---------------- Outreach & communications ---------------- */
 {fn:'outreach', area:'out-relations',
  proc:{id:'speakerreq', name:'Speaker requests', d:'Log invitations for the president and officials, recommend which to accept and prepare the briefings.', rating:3, why:'A steady flow of text requests and briefings that follow a pattern. Logging and briefing drafts help; choosing who the president speaks to stays with people.'},
  intro:'The president and eleven senior officials are invited to speak far more often than they can. Each invitation is logged, weighed and, if accepted, turned into a briefing. Walk an invitation from inbox to briefing.',
  steps:[
  {n:'Log each invitation', who:'Two speaker coordinators', vol:'About 60 invitations a month', sys:'Shared mailbox, request tracker, officials’ calendars',
   notes:'Invitations arrive by email, letter and the website. Coordinators read each one and log the event, date, place, audience, organiser and what is asked: a keynote, a panel, a lecture or a conversation on stage.',
   pain:'Forty minutes per invitation, much of it hunting for the date and audience in long emails. Invitations sit unlogged for a week, and two were found after the event had passed.',
   p:'extract text mid low', alt:'shape:route', best:'extract', ok:'classify rules', auto:'review', autoOk:'auto',
   why:'Pull the event details into the tracker as each invitation arrives, and flag dates that fall in the quiet period before a rate decision. Coordinators check the entries before the monthly review.',
   disc:[['Quiet periods','Officials do not speak publicly about policy in the days before each rate decision.','Rule: flag any invitation that falls in a quiet period, from the published calendar.'],['The date in paragraph three','Most invitations are long emails with the key facts scattered through them.','Fix first: point organisers to a short request form on the website.']],
   fv:'high mid', reality:'Quick to do on plain emails. Medium value: about 40 hours a month, and no invitation missed.',
   metric:'Days from arrival to logged invitation, and invitations missed', g:'threshold sampling', hyp:'Every invitation logged within a day, with quiet-period clashes flagged.', data:'Two years of invitations and the tracker entries made from them, the quiet-period calendar.'},
  {n:'Recommend which to accept', who:'Head of outreach and the president’s chief of staff', vol:'About 60 invitations a month, 15 accepted', sys:'Request tracker, contact system, monthly meeting',
   notes:'Once a month they go through the invitations and recommend which each official should accept, weighing audience, region, timing, the message the Bank wants to make, and what each official has already agreed to.',
   pain:'Choices lean towards large city audiences and organisers who ask often. Two regions have had no visit from an official in two years.',
   p:'suggest structured mid mid', alt:'shape:decide input:text', best:'recommend', ok:'retrieve rules', auto:'assist',
   why:'Rank the month’s invitations by audience, reach and the regions and sectors that have not heard from an official lately, with the reasons shown. The head of outreach and the chief of staff decide.',
   disc:[['Coverage, not loudness','The organisers who ask most often are not the audiences the Bank most needs to reach.','Value: rank on coverage gaps, using the contact records.'],['A public choice','Who the president speaks to is noticed, and sometimes criticised.','Risk: people decide and can explain every choice.']],
   fv:'mid mid', reality:'Useful once the contact records are complete enough to show coverage. Assist only: the choice is public.',
   metric:'Regions and sectors without a visit from an official in a year', g:'bias logging sampling', hyp:'Every region and major sector hears from an official at least once a year.', data:'The request tracker, the contact system, past acceptances.'},
  {n:'Prepare the briefing', who:'Outreach officers and a regional economist', vol:'About 15 briefings a month', sys:'Word template, contact system, speech archive, regional data',
   notes:'For each accepted event, an officer assembles a briefing: the organiser and audience, who else is speaking, local economic data, what the official has said before on likely topics, and the questions to expect.',
   pain:'A day and a half per briefing, gathered from six places: more than one person’s full time. Briefings sometimes miss that the official met the same organiser last year.',
   p:'draft text mid mid', alt:'shape:summarize', best:'draft retrieve', ok:'summarize', auto:'review',
   why:'Assemble a first draft from the speech archive, the contact records and the regional data, with every source linked, for the officer to check and finish.',
   disc:[['Half the meetings are missing','Only about half of meetings with contacts are logged in the contact system.','Prepare: a briefing is only as good as the contact records behind it.'],['Past remarks','Every speech and question-and-answer transcript since 2012 is in the archive.','Data: ready for retrieval.']],
   fv:'mid high', reality:'High value: more than a person’s full time each month. Prepare the contact records first, or the drafts will miss what matters.',
   metric:'Officer hours per briefing, and facts corrected by the official’s office', g:'sampling logging', hyp:'A briefing in half a day, with every past contact and remark included.', data:'The speech archive, the contact system, regional data, past briefings.'},
 ]},

 {fn:'outreach', area:'out-media',
  proc:{id:'socialmon', name:'Social media monitoring', d:'Filter mentions of the Bank, spot misinformation and scams, and summarise the day for senior staff.', rating:3, why:'High volume and a real risk. A better search does most of the sorting, the daily summary is a quick win, and judging what is false stays with people.'},
  intro:'Thousands of posts and articles mention the Bank each day. Most are harmless; a few are scams, rumours or fake accounts that could mislead the public. Walk a day of monitoring.',
  steps:[
  {n:'Filter the day’s mentions', who:'Two digital communications officers', vol:'About 2,500 mentions a day, over 20,000 on decision days', sys:'Social listening service, spreadsheet',
   notes:'The listening service collects every public post and article that mentions the Bank. Officers skim the feed each morning and tag what is relevant: rates, cash, jobs, scams, the president.',
   pain:'Seven mentions in ten are about other things called Meridian: a hotel chain, a football club and a shopping centre. Officers spend the first two hours of each day clearing them out.',
   p:'route text high low', alt:'shape:check', best:'rules', ok:'classify', auto:'auto', autoOk:'review',
   why:'Most of the noise comes from a search that is too broad. Rewrite the listening query with exclusions and use the service’s own topic tags, and the feed shrinks to what matters. Try classification only if real noise remains.',
   disc:[['A query from 2019','The search query was written when the account was opened and has never changed.','Fix first: add exclusions for the hotel, the club and the shopping centre.'],['Tags built in','The listening service already tags topic and language.','Feasibility: a setting, not a project.']],
   fv:'high mid', reality:'Simple configuration. Medium value: two hours a day back, and a feed people can read.',
   metric:'Share of mentions in the feed that are about the Bank, and minutes spent filtering each morning', g:'sampling rollback', hyp:'Nine mentions in ten in the feed are about the Bank.', data:'The listening query, a month of tagged mentions.'},
  {n:'Spot misinformation and scams', who:'Digital communications officers', vol:'About 300 relevant mentions a day', sys:'Listening service, published statements, fraud team contacts',
   notes:'Officers look for false claims that could spread: fake accounts posing as the Bank or the president, scams offering “central bank” investments, doctored banknotes, and rumours about cash limits or bank failures.',
   pain:'A fake account using the president’s photo gathered 8,000 followers before anyone noticed. Spikes that start on a weekend are seen on Monday.',
   p:'check text high high', alt:'input:media', best:'anomaly', ok:'classify retrieve vision', auto:'assist', autoOk:'review',
   why:'Watch for sudden spikes and for new accounts using the Bank’s name or images, and match claims against what the Bank has actually said. Officers judge what is false and whether it matters.',
   disc:[['Spikes come first','Most past incidents showed up as a sudden jump in mentions hours before anyone read the posts.','Value: alert on unusual volume, around the clock.'],['Calling something false','Labelling a post as misinformation is a public judgment the Bank must be able to defend.','Risk: a person decides every case and every response.']],
   fv:'mid high', reality:'High value and high stakes. Feasible as alerts for a person, not as automatic judgments.',
   metric:'Hours from first post to the Bank noticing, and false alerts a week', g:'threshold escalation logging', hyp:'Every fast-spreading false claim noticed within two hours, day or night.', data:'The mention feed with volumes, past incidents, the Bank’s published statements.'},
  {n:'Write the daily media summary', who:'Digital communications officers', vol:'Daily, read by about 40 senior staff', sys:'Listening service, news clippings service, Word',
   notes:'Every morning an officer writes a two-page summary of what the press and social media said about the Bank and the economy, with links, for senior staff.',
   pain:'Ninety minutes each morning, about 30 hours a month. On decision days it goes out late, because there is ten times as much to read.',
   p:'summarize text high low', alt:'shape:draft', best:'summarize', ok:'classify draft', auto:'review', autoOk:'auto',
   why:'Draft the summary from the filtered feed and the clippings, grouped by topic with a link to every item, for the officer to check before it goes out.',
   disc:[['Internal only','The summary goes to staff, not the public.','Keep: errors are cheap and readers catch them, but an officer still checks it.'],['The clippings licence','The news clippings service limits how much of each article can be copied.','Rule: summarise and link; never paste whole articles.']],
   fv:'high mid', reality:'A quick win on a clean feed, once the search is fixed. Medium value: about 30 hours a month and a summary on time on decision days.',
   metric:'Minutes to produce the summary, and items readers say were missed', g:'sampling', hyp:'The summary out by 8:30 every day, decision days included.', data:'The filtered mention feed, the clippings service, past summaries.'},
 ]},

 {fn:'outreach', area:'out-pubs',
  proc:{id:'plainlang', name:'Plain-language summaries of policy statements', d:'Draft a plain-language summary of each policy statement, check it against the statement and release it with approval.', rating:2, why:'Eight a year, market-sensitive and already done with great care. Drafting and checking aids help under the deadline; people approve every word.'},
  intro:'After each rate decision the Bank publishes its policy statement, written for markets, and a short summary in plain words for everyone else. The summary must say exactly what the statement says, no more, and go out at the same moment. Walk a decision day.',
  steps:[
  {n:'Pre-draft a summary for each outcome', who:'Two communications writers', vol:'8 decisions a year, three versions each', sys:'Word, scenario statements, past summaries',
   notes:'In the week before each decision, the writers prepare a short plain-language summary for each possible outcome (hold, raise or cut) from the staff’s draft scenario statements. Only the version that matches the decision is used.',
   pain:'Three days of drafting each cycle, much of it rewriting the same explanations of how rates affect borrowing and saving.',
   p:'draft text low high', alt:'stakes:mid', best:'draft', ok:'retrieve summarize', auto:'assist',
   why:'Draft each version from the scenario statement and past summaries, at a reading age of about twelve, for the writers to rewrite. Nothing leaves the restricted environment, and nothing is published without approval.',
   disc:[['Restricted until release','Scenario statements are among the most sensitive documents the Bank holds.','Data: only inside the restricted environment used for policy work.'],['Plain words, same meaning','A plain phrase can say more than the statement means, such as “rates will fall again”.','Risk: every sentence must match the statement; the next step checks it.']],
   fv:'mid mid', reality:'Feasible only inside the restricted environment. Medium value: days saved each cycle, on the page most of the public reads.',
   metric:'Writer days per cycle, and sentences changed at approval', g:'logging escalation sampling', hyp:'Three days of drafting cut to one, with no change in meaning.', data:'Past statements and their summaries, the scenario statements, the reading-age target.'},
  {n:'Check the summary against the final statement', who:'An economist in the policy secretariat', vol:'8 a year, in the hour before release', sys:'Final statement, draft summary, Word',
   notes:'Once the decision is final, the matching summary is updated and an economist checks every sentence against the final statement. Any sentence that says more, or less, than the statement is changed.',
   pain:'The check happens in a locked room with an hour to spare. Last year a summary said inflation “has peaked” when the statement said only that it “may be near its peak”, and the press noticed.',
   p:'check text low high', alt:'shape:decide', best:'extract', ok:'retrieve anomaly', auto:'assist',
   why:'Line up each sentence of the summary with the passage of the statement it rests on, and flag any sentence with no support or a stronger claim. The economist decides every change.',
   disc:[['Shades of meaning','Markets read “may be near” and “has” very differently.','Risk: flags help, but the economist still reads every sentence.'],['One hour','The final statement is fixed only an hour before release.','Feasibility: the check must take minutes, inside the restricted environment.']],
   fv:'mid mid', reality:'Narrow and useful under a hard deadline. High stakes: assist only.',
   metric:'Unsupported sentences found before release, and corrections after release', g:'logging escalation', hyp:'No published summary says more than the statement.', data:'Final statements with their published summaries.'},
  {n:'Approve and release at the set time', who:'Head of communications, the web team and the press office', vol:'8 a year, at 2:00pm on decision days', sys:'Content management system, social media accounts, email',
   notes:'The head of communications approves the final text by email. A web officer then publishes the statement and summary by hand at exactly 2:00pm, and the press office posts them on social media.',
   pain:'Last year the summary went live four minutes late because the approval email was stuck. Publishing by hand under time pressure is how pages go live early.',
   p:'coordinate structured low high', alt:'shape:check', best:'rules', ok:'agent', auto:'review',
   why:'Approval and release are workflow, not a judgment about words. Record the approval in the publishing system and let it release the approved pages at the set time. A person still approves; the clock does the rest.',
   disc:[['Early is worse than late','A page live a minute early leaks a market-moving decision.','Rule: schedule the release, with the page locked until the set time.'],['Approval in one place','Approvals now arrive by email, by phone and in person.','Fix first: one recorded approval, in the publishing system.']],
   fv:'high mid', reality:'Standard publishing features, configured with care. Medium value: the risk of an early or late release removed.',
   metric:'Seconds between the set time and publication, and releases with a recorded approval', g:'logging rollback', hyp:'Every summary live at exactly the set time, with a recorded approval.', data:'The decision calendar, and the publishing system’s scheduling and approval settings.'},
 ]},

 {fn:'outreach', area:'out-pubs',
  proc:{id:'website', name:'Website updates', d:'Take in content requests from across the Bank, check pages for accessibility and publish them, and deal with the archive.', rating:3, why:'Steady volume, but the biggest problems are page ownership and an old archive. Accessibility checks are rules; the archive is a real prize that is blocked for now.'},
  intro:'The website holds 4,000 pages and every publication since 1990. Thirty teams ask for changes, every page must be accessible, and nothing should stay up once it is out of date. Walk a month on the web team.',
  steps:[
  {n:'Take in content requests', who:'Web team of four', vol:'About 250 requests a month from 30 teams', sys:'Shared mailbox, request form, content management system',
   notes:'Teams across the Bank email the web team to add or change pages: a new report, a corrected date, a staff change. The web team works out which page is meant, makes the change and asks the requester to check it.',
   pain:'Four requests in ten are small corrections the owning team could make itself. Nobody owns 1,100 of the site’s 4,000 pages, so outdated pages stay up.',
   p:'coordinate text high low', alt:'shape:route', best:'fix', ok:'classify rules', auto:'review',
   why:'The queue exists because nobody owns most pages and only the web team can edit. Give every section an owner, let trained owners make simple changes with a review, and use one request form. Sorting a queue that should not exist is the wrong first project.',
   disc:[['Orphan pages','About 1,100 pages have no owning team.','Fix first: assign an owner to every section, with a review date.'],['Owners can edit','The content management system supports editing by section, with approval.','Feasibility: a permissions change and a short training course.']],
   fv:'high mid', reality:'A process change the web team can lead. Medium value: fewer requests and a site that stays current.',
   metric:'Requests a month, and pages past their review date', g:'logging', hyp:'Halve the request queue and give every page an owner.', data:'The page inventory with owners and last-updated dates.'},
  {n:'Check pages for accessibility', who:'Web team', vol:'About 400 new or changed pages and PDFs a month', sys:'Accessibility checker, screen reader, content management system',
   notes:'Every page must meet the accessibility standard. The automated checker is run across the whole site once a quarter; in between, the team checks only what they remember to.',
   pain:'Each quarterly run finds about 900 new failures, mostly missing image text, empty links and headings out of order, all of them already live.',
   p:'check structured high mid', alt:'input:text', best:'rules', ok:'draft vision', auto:'auto', autoOk:'review',
   why:'These failures can be found by rule. Run the checker on every page before it is published and hold back the ones that fail. Keep a screen-reader check by a person for what rules cannot judge, such as whether image text makes sense.',
   disc:[['Rules find some, not all','Automated checks catch only a share of accessibility problems.','Keep: a person still tests key pages with a screen reader.'],['Already licensed','The checker is already licensed and can run when a page is published.','Feasibility: a setting in the publishing workflow.']],
   fv:'high mid', reality:'Configuration of a tool the Bank already has. Medium value: failures caught before they go live.',
   metric:'Accessibility failures found live, and pages held back before publication', g:'logging sampling', hyp:'No page goes live with a failure a rule can catch.', data:'The checker’s rules and the publishing workflow.'},
  {n:'Make old publications accessible', who:'Web team and a records officer', vol:'About 11,000 PDFs published before 2016', sys:'Website archive, PDF editor',
   notes:'The site still carries every report, bulletin and speech since 1990 as PDFs. Most have no tags for screen readers, a third are scans of typed pages, and many contain tables of figures.',
   pain:'The Bank cannot say when the archive will meet the standard. Three complaints last year came from researchers using screen readers.',
   p:'draft media low mid', alt:'shape:extract', best:'draft', ok:'vision extract', auto:'review',
   why:'Turning old scans and tables into accessible documents is possible, but errors on old tables and charts are still common, and every document would need checking by hand. Park it, and decide first which documents people still read.',
   disc:[['Nine in ten unread','Nine old PDFs in ten had no visits last year.','Value: fix the 1,000 most-read documents properly, and the rest when someone asks.'],['Tables of figures','Old statistical tables lose their meaning when the tagging is wrong.','Feasibility: low for tables until the tools improve.']],
   fv:'low mid', reality:'A real obligation, but blocked by old scans and tables. Park it, and start with the documents people actually read.',
   metric:'Most-read archive documents that meet the standard', g:'sampling', hyp:'Every archive document people still read is accessible within a year.', data:'Visit counts for archive documents, a sample of 50 old PDFs.'},
 ]},

 /* ---------------- Legal, compliance & audit ---------------- */
 {fn:'legal', area:'leg-records',
  proc:{id:'retention', name:'Records retention', d:'Classify records against the retention schedule, honour legal holds and approve disposals.', rating:3, why:'Millions of files and a schedule nobody can apply by hand. Classification helps once the schedule is simpler; holds need a hard block, and disposal stays a signed decision.'},
  intro:'The law and the Bank’s retention schedule say how long each kind of record is kept, and when it should be destroyed. Destroy too early and the Bank breaks the law; keep everything and the cost and risk pile up. Walk a record from filing to disposal.',
  steps:[
  {n:'Classify records against the schedule', who:'Records officers and 40 departmental records coordinators', vol:'About 6 million files on shared drives, 310 record classes', sys:'Records management system, shared drives, retention schedule',
   notes:'Each record should be filed with its record class, which sets how long it is kept. Staff file about a third of their documents in the records system; the rest sit on shared drives with no class at all.',
   pain:'Coordinators cannot tell what most shared-drive files are, so nothing on the drives is ever disposed of. The drives grow by a fifth each year.',
   p:'route text high mid', alt:'shape:extract', best:'classify', ok:'rules extract', auto:'review',
   why:'Propose a record class for each file from its content, folder and author, and file the confident ones; coordinators confirm the rest. Simplify the schedule first, or the tool will be choosing between classes people cannot tell apart.',
   disc:[['Three hundred and ten classes','Many classes overlap, such as “project files” and “programme records”.','Prepare: merge them into about 40 broad classes, as many records teams now do.'],['Folders say a lot','Most shared-drive folders belong to one team and one kind of work.','Data: the folder and team narrow most choices to a few classes.']],
   fv:'mid high', reality:'High value: nothing can be disposed of until it is classified. Prepare by simplifying the schedule.',
   metric:'Share of files with a record class, and classes corrected by coordinators', g:'threshold sampling logging', hyp:'Nine files in ten classified within a year, with coordinators checking only the uncertain ones.', data:'The retention schedule, files already classified in the records system, the shared-drive folder structure.'},
  {n:'Check legal holds before disposal', who:'Litigation counsel and records officers', vol:'About 15 active holds covering 120 staff', sys:'Hold spreadsheet, email, records management system',
   notes:'When the Bank expects litigation or an investigation, a lawyer issues a hold: the records of named staff and topics must not be destroyed. Holds are kept in a spreadsheet, and records officers check it by hand before each disposal run.',
   pain:'The records system cannot see the holds, so a disposal run can include held records if the spreadsheet is missed. Last year a box under hold was destroyed and had to be reported to the court.',
   p:'check structured mid high', alt:'shape:coordinate', best:'rules', ok:'anomaly', auto:'review',
   why:'Once a lawyer has defined a hold, whether it covers a record is an exact match on staff, topic, class and dates. Record holds in the records system itself, and block disposal of anything they cover. Lawyers decide the holds; the system enforces them.',
   disc:[['A wrong disposal is serious','Destroying records under hold can bring court sanctions and lose the Bank its case.','Rule: held records cannot be disposed of, and no records officer can override the block.'],['Holds without an end','Six of the fifteen holds relate to matters closed years ago.','Fix first: review every hold each quarter, and release the ones no longer needed.']],
   fv:'high high', reality:'Standard records system features, configured. High value: a serious legal risk removed.',
   metric:'Disposal runs checked against holds automatically, and held records destroyed', g:'logging escalation', hyp:'No record under hold is ever destroyed.', data:'The hold register, with named staff, topics and dates, inside the records system.'},
  {n:'Approve disposals', who:'Heads of department and the records manager', vol:'About 900 boxes and 400,000 electronic files a year', sys:'Records management system, disposal lists, offsite store',
   notes:'When records reach the end of their retention period, the records manager sends each head of department a list for approval. Approved paper is shredded under witness, and electronic files are deleted.',
   pain:'Lists run to thousands of lines of file titles. Some heads sign without reading; others refuse to approve anything, and the offsite store costs $60,000 more each year.',
   p:'decide structured mid high', alt:'shape:check', best:'recommend', ok:'summarize anomaly', auto:'assist',
   why:'Summarise each disposal list by class and date, and flag the items that may still matter: titles that mention open matters, staff under a hold, or events of historical interest. The head of department decides, and the decision is recorded.',
   disc:[['Signed unread','A head of department approved a 6,000-line list in four minutes.','Risk: show a summary and the flagged items, so approval is a real decision.'],['History matters','Some records have historical value after their retention period ends.','Keep: the archivist sees anything flagged as historical before disposal.']],
   fv:'mid mid', reality:'Useful, and high stakes. Assist only: a person signs every disposal.',
   metric:'Weeks to approve a list, and flagged items held back', g:'logging escalation sampling', hyp:'Every list approved within a month, with the risky items seen by a person.', data:'Past disposal lists and approvals, the hold register, the retention schedule.'},
 ]},

 {fn:'legal', area:'leg-audit',
  proc:{id:'auditreport', name:'Drafting audit reports', d:'Draft findings from workpapers, cross-reference the report and agree management’s action plan.', rating:3, why:'Regular, text-heavy and read closely. Drafting and cross-referencing save real time; findings stay with auditors, and the slowest part is a process problem.'},
  intro:'Internal audit runs about 40 audits a year. Each ends in a report to management and the audit committee: what was found, why it matters and what management will do about it. Walk a report from workpapers to agreed actions.',
  steps:[
  {n:'Draft findings from the workpapers', who:'Auditors', vol:'About 40 audits a year, 6 findings each', sys:'Audit management system, workpapers, Word',
   notes:'At the end of fieldwork, auditors write each finding in the standard four parts: what was found, the rule it breaks, the cause and the effect. They work from their workpapers, test results and interview notes.',
   pain:'Two to three days per report, and audit managers rewrite most findings because the four parts are muddled.',
   p:'draft text mid high', alt:'shape:summarize', best:'draft', ok:'summarize retrieve', auto:'assist',
   why:'Draft each finding in the four-part format from the workpapers, citing the workpaper behind each sentence, for the auditor to rewrite. The auditor owns every word and the rating.',
   disc:[['Findings affect careers','Managers named in findings take them personally, and some findings are discussed at the audit committee.','Risk: the auditor writes and owns every finding.'],['One tool, not two','Control-testing write-ups already use the general assistant staff have.','Feasibility: use the same assistant, inside the audit system.']],
   fv:'high mid', reality:'Feasible with what the team already has. Medium value: days per report, and fewer rewrites.',
   metric:'Days from end of fieldwork to draft report, and findings rewritten by managers', g:'logging sampling escalation', hyp:'A draft report within three days of fieldwork, in the four-part format.', data:'Workpapers, past reports with managers’ edits, the finding format.'},
  {n:'Cross-reference the report to the workpapers', who:'Audit quality reviewer', vol:'About 40 reports a year, 120 statements each', sys:'Audit management system, draft report',
   notes:'Before a report goes to management, a reviewer who was not on the audit checks that every statement of fact is backed by a workpaper, and writes the reference beside it.',
   pain:'Two days per report, and reports wait a week in the queue for the one reviewer.',
   p:'check text mid mid', alt:'shape:lookup', best:'extract', ok:'retrieve anomaly', auto:'review',
   why:'Match each statement to the workpaper that supports it, and list the statements with no support or a weak match. The reviewer reads the list and the doubtful matches, not every page.',
   disc:[['One system','Workpapers and drafts are both held in the audit management system.','Data: ready.'],['Support, not proof','A match shows where the evidence is, not that it proves the statement.','Keep: the reviewer judges whether the evidence is enough.']],
   fv:'high mid', reality:'Quick to do inside one system. Medium value: a week off every report.',
   metric:'Reviewer days per report, and unsupported statements found after issue', g:'sampling logging', hyp:'Cross-referencing done in half a day, with every unsupported statement listed.', data:'Past reports with their references, and the workpapers.'},
  {n:'Agree management’s action plan', who:'Audit managers and the managers audited', vol:'About 240 findings a year', sys:'Email, Word, audit management system',
   notes:'The draft report goes to the managers concerned, who write a response and an action plan for each finding: what they will do, who owns it and by when. Drafts go back and forth by email until both sides agree.',
   pain:'Seven weeks on average from draft to issued report. A third of actions say only “management will review the process”, with no owner or date.',
   p:'coordinate text mid mid', alt:'shape:draft', best:'fix', ok:'draft agent', auto:'review',
   why:'The delay is the process, not the writing. Agree the facts in a closing meeting before the draft is sent, require an owner, a date and the evidence that will close each action, and set a ten-day deadline for responses in the audit charter.',
   disc:[['Five rounds of email','Reports go through five rounds of email on average before they are agreed.','Fix first: agree the facts in a closing meeting, then send the draft.'],['Vague actions','Actions without owners or dates are the ones still open a year later.','Rule: no action is accepted without an owner, a date and closing evidence.']],
   fv:'high mid', reality:'A change audit can make itself, with the audit committee’s backing. Medium value: weeks off every report, and actions that can be tracked.',
   metric:'Days from draft to issued report, and actions with an owner and a date', g:'logging', hyp:'Reports issued within three weeks of the draft, with every action owned and dated.', data:'Report timelines and action plans from the last two years.'},
 ]},

 {fn:'legal', area:'leg-policy',
  proc:{id:'conflicts', name:'Conflict-of-interest disclosures', d:'Collect staff holdings and outside interests each year, check them against the rules and decide what to do.', rating:3, why:'A yearly peak of personal financial data checked against clear rules. Extraction and rules carry the checking; decisions about people stay with compliance.'},
  intro:'Staff who see confidential policy and supervisory information must not profit from it, or let outside interests sway their work. Each year they disclose what they hold and what else they do, and compliance checks it. Walk the annual disclosure round.',
  steps:[
  {n:'Turn statements into a holdings list', who:'Compliance officers', vol:'About 650 covered staff a year, 9,000 pages of statements', sys:'Disclosure form, brokerage and pension statements, spreadsheet',
   notes:'Staff in policy-sensitive roles disclose every holding each year and attach statements from their brokers and pension providers. Officers key each holding into a spreadsheet so it can be checked.',
   pain:'Statements come in about 40 layouts, and a few are photographs. Keying takes three officers most of February and March.',
   p:'extract text high mid', alt:'input:media', best:'extract', ok:'rules', auto:'review',
   why:'Read each statement and list its holdings with their security identifiers, sending low-confidence lines to an officer. Better still, ask covered staff to let their brokers send holdings directly as data.',
   disc:[['Personal financial data','Statements show the wealth of staff and their families.','Data: only inside the compliance system, with access limited to the review team.'],['Broker feeds','The six brokers most used by staff can send holdings as data.','Fix first: ask staff to authorise a feed, and extract only the rest.']],
   fv:'mid mid', reality:'Worth doing, with great care over personal data. Medium value: about two months of keying each year.',
   metric:'Officer hours keying holdings, and holdings missed or mis-keyed', g:'privacy threshold sampling', hyp:'Holdings lists ready within a week of each disclosure.', data:'A sample of past statements with the holdings keyed from them, a list of security identifiers.'},
  {n:'Check holdings against the restricted list', who:'Compliance officers', vol:'About 650 holdings lists, 21,000 holdings', sys:'Restricted list, spreadsheet, trade records',
   notes:'Officers compare each holding with the restricted list: shares and bonds of the 210 supervised banks and their parent companies, and funds that concentrate on banks. They also check for trades in the days before rate decisions.',
   pain:'The comparison is done by eye on names, so a bank listed under its parent company’s name is easy to miss. Each officer gets through about 200 holdings an hour.',
   p:'check structured high mid', alt:'shape:route', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Matching holdings to the restricted list by security identifier is an exact rule, and so is checking trade dates against the blackout calendar. Run it on every list and send each match to an officer. No AI is needed, and names are the wrong key.',
   disc:[['Names are the wrong key','The same bank appears under several names and codes.','Data: match on security identifiers, kept current with the supervised-bank list.'],['The list goes stale','Banks merge and change names, and the restricted list was last updated in the spring.','Rule: refresh the list monthly from supervision’s records.']],
   fv:'high mid', reality:'Simple engineering once holdings carry identifiers. Medium value: faster checks and no missed matches.',
   metric:'Matches found by rule against matches found by eye, and restricted holdings found later', g:'logging sampling', hyp:'Every holdings list checked in seconds, with no missed restricted holding.', data:'The restricted list with identifiers, the holdings lists, the blackout calendar.'},
  {n:'Review outside interests and decide', who:'Compliance officers and the ethics counsel', vol:'About 400 disclosures with an outside interest, 40 needing action', sys:'Disclosure forms, case notes, ethics rules',
   notes:'Staff also disclose outside roles and interests: a directorship, a side business, a spouse who works at a supervised bank. Officers read each one, ask questions, and decide whether to approve it, add a restriction such as stepping back from certain work, or require the interest to end.',
   pain:'Similar cases get different answers from different officers, and each decision takes a week of emails. Staff wait to take up roles they have been offered.',
   p:'decide text mid high', alt:'shape:check', best:'recommend', ok:'retrieve summarize', auto:'assist',
   why:'Pull up the rule and the most similar past decisions for each disclosure, and suggest the questions to ask. The officer decides, and the ethics counsel reviews anything that limits someone’s work.',
   disc:[['Decisions affect jobs','A restriction can move someone off work they were hired to do.','Risk: a person decides and explains every outcome.'],['Past decisions are scattered','Ten years of decisions sit in case notes, not in one searchable place.','Prepare: gather past decisions into one record, with the reasons.']],
   fv:'mid mid', reality:'Useful for consistency, with personal data and careers at stake. Assist only.',
   metric:'Days to a decision, and similar cases decided differently', g:'privacy logging escalation bias', hyp:'Decisions within a week, consistent with past cases.', data:'Past decisions with their reasons, the ethics rules, current disclosures.'},
 ]},

 {fn:'legal', area:'leg-policy',
  proc:{id:'minutes', name:'Board minutes', d:'Record board and committee meetings, draft the minutes and take them through review to approval.', rating:2, why:'About 40 meetings a year, high stakes and confidential. A drafting aid helps the secretary; transcription is already in the boardroom, and the review round is a process problem.'},
  intro:'The board and its committees meet about 40 times a year. The minutes are the legal record of what they decided, and they are confidential. Walk a set of minutes from meeting to approval.',
  steps:[
  {n:'Record and transcribe the meeting', who:'Corporate secretary', vol:'About 40 board and committee meetings a year', sys:'Boardroom recording system, notebook, board portal',
   notes:'The secretary takes notes during each meeting. Where the chair agrees, the meeting is also recorded, and afterwards the secretary listens again to the parts the notes missed.',
   pain:'About three hours of listening after each recorded meeting. Some directors prefer not to be recorded at all.',
   p:'extract media low mid', alt:'input:tacit', best:'speech', ok:'summarize', auto:'review',
   why:'At 40 meetings a year, a dedicated tool would not pay back. The boardroom’s recording system can already produce a transcript inside the Bank’s network; switch it on with the chair’s agreement, and use the transcript only to check the notes.',
   disc:[['Recordings are records','A recording kept after the minutes are approved can be demanded in litigation.','Rule: delete the recording and transcript once the minutes are approved, as the retention schedule says.'],['Off the record','Directors can ask for any item to be discussed without recording.','Keep: the secretary’s notes remain the main record.']],
   fv:'high low', reality:'Easy with what the Bank already has, and too small to build anything for.',
   metric:'Hours spent listening to recordings after each meeting', g:'privacy logging', hyp:'Notes checked against the transcript in under an hour after each meeting.', data:'The recording system’s transcript setting, and the chair’s agreement.'},
  {n:'Draft the minutes', who:'Corporate secretary', vol:'About 40 sets a year, 8 to 15 pages each', sys:'Notes, transcript, board papers, minutes template',
   notes:'From the notes, the transcript and the papers, the secretary drafts the minutes: who attended, interests declared, a short account of each discussion, and every decision and action with its owner.',
   pain:'Two days per set, about 80 days a year, and drafts are often a week late. Actions are sometimes missed and found only when a director asks.',
   p:'draft text low high', alt:'shape:summarize', best:'draft', ok:'summarize extract', auto:'assist',
   why:'Draft the minutes in the house format from the notes, the transcript and the papers, listing every decision and action separately. The secretary rewrites the account of discussion and owns the record.',
   disc:[['Confidential beyond most','Board papers include supervisory and policy matters that few staff may see.','Data: only inside the restricted environment used for board work.'],['What is not said','Minutes record decisions and the substance of debate, not every remark.','Risk: the secretary decides what the record says, and the chair approves it.']],
   fv:'mid mid', reality:'Medium value in time and in actions not missed. High stakes and confidential: assist only, in a restricted environment.',
   metric:'Days from meeting to draft minutes, and actions missed', g:'privacy logging escalation', hyp:'Draft minutes within two days of every meeting, with no action missed.', data:'Past approved minutes, the house template, notes and transcripts.'},
  {n:'Review and approve the minutes', who:'General counsel, the chair and the directors', vol:'About 40 sets a year', sys:'Email, Word, board portal',
   notes:'The draft goes to the general counsel, then to the chair, then to all directors for comment. Comments come back by email on different versions, and the minutes are approved at the next meeting.',
   pain:'Three to five weeks per set. Last year two directors commented on an old version, and their changes were lost.',
   p:'coordinate text low high', alt:'shape:check', best:'fix', ok:'rules', auto:'assist',
   why:'Version chaos is a process problem. Circulate one draft in the board portal the Bank already uses for papers, collect comments there by a set date, and record the chair’s approval in the same place.',
   disc:[['The portal is there','The board portal can take comments on a document, but the feature has never been switched on.','Fix first: one version, one place, one deadline.'],['Approval is the chair’s','Once approved, the minutes are the legal record.','Keep: no tool changes the approved text.']],
   fv:'high mid', reality:'A change the secretary’s office can make with tools it already has. Medium value: weeks saved per set and no lost comments.',
   metric:'Days from draft to approval, and comments lost between versions', g:'logging', hyp:'Minutes ready for approval within two weeks of every meeting.', data:'The board portal’s comment and approval settings.'},
 ]},
];
